#!/bin/sh
# Incrusta la procedencia en cada imagen publicada (Impeccable: "every shipping raster carrying its provenance").
# Ejecutar después de scripts/assets.mjs, que regenera los archivos.
IMP=/c/Users/User/.claude/skills/impeccable/scripts/impeccable
e() { sh "$IMP" embed-prompt "public/img/$1" --prompt "$2" >/dev/null && echo "ok $1"; }
L="Origen: captura real de lanzamet.com (producto de Fernando Montelongo; datos de demostración), de p-projects/lanzamet-video/assets"
for f in retrato-recorte-1086.webp retrato-recorte-720.webp; do e "$f" "Origen: fotografía propia de Fernando Montelongo (profile.png, autorizada 28-10-2026), recortada con su matte (assets-src/portrait-matte.png); el iris de cada ojo se sustituye por esclera (relleno por filas a partir de la esclera visible) para animarlo aparte; scripts/eyes.mjs"; done
for f in ojo-izq-iris.png ojo-der-iris.png; do e "$f" "Origen: iris y pupila recortados de profile.png (foto propia, autorizada); la parte tapada por el párpado se reconstruye por simetría radial; scripts/eyes.mjs"; done
for f in ojo-izq-mask.png ojo-der-mask.png; do e "$f" "Origen: máscara de la apertura del ojo, trazada a mano sobre ampliaciones de profile.png (assets-src/eyes/grid-*.png) y rasterizada por scripts/eyes.mjs"; done
for f in lanzamet-hoy-1600.webp lanzamet-hoy-900.webp lanzamet-mar-1600.webp lanzamet-mar-900.webp lanzamet-donde-1600.webp lanzamet-donde-900.webp lanzamet-noche-1600.webp lanzamet-noche-900.webp lanzamet-movil-900.webp; do e "$f" "$L, redimensionada a WebP por scripts/assets.mjs"; done
e isla-mask.png "Origen: silueta de Lanzarote extraída del mapa base de LanzaMet (capture/map-base.png), guardada en assets-src/isla.png y convertida a máscara alfa limpia por scripts/assets.mjs"
e haircloud-datos.webp "Origen: diagrama de datos del anteproyecto de HairCloud, repositorio público github.com/fmoorenoo/HairCloud (anteproyecto/media), convertido por scripts/assets.mjs"
for f in hc-login.webp hc-barberias.webp hc-detalle.webp hc-reserva.webp hc-agenda.webp; do e "$f" "Origen: captura real de la app HairCloud (github.com/fmoorenoo/HairCloud) compilada y ejecutada el 30-10-2026 en un emulador Android 15 (Pixel 7), con su API Flask y PostgreSQL en local y datos de demostración (terceros anonimizados); recortada por scripts/assets.mjs"; done
for f in kora-formatxp.webp kora-carboncarbon.webp kora-autosmr.webp kora-cm4costaviva.webp kora-doce12ia.webp kora-bermeja.webp kora-masdache.webp kora-ymelbet.webp; do e "$f" "Origen: captura cuadrada (1280×1280) de la portada pública de la web, hecha el 30-10-2026 con scripts/kora-shots.mjs (aviso de cookies cerrado con la opción mínima); web publicada por el equipo KORA Digital Solutions"; done
for f in ac-login.webp ac-inicio.webp ac-incidencias.webp ac-alertas.webp ac-emergencias.webp ac-formaciones.webp; do e "$f" "Origen: captura real de la app ACESLAN (github.com/FabioGonzalez2005/ACESLAN) compilada el 30-10-2026 y ejecutada en un emulador Android 15 contra el backend local (fmoorenoo/backend-aceslan, Laravel + MariaDB) con los seeders de demostración del proyecto; recortada por scripts/assets.mjs"; done
for f in ac-panel-incidencias-900.webp ac-panel-incidencias-1440.webp ac-panel-alertas-900.webp ac-panel-alertas-1440.webp; do e "$f" "Origen: captura del panel web de administración de ACESLAN (fmoorenoo/backend-aceslan) servido en local el 30-10-2026 con los seeders de demostración, sesión de moderador de demo; hecha con scripts/aceslan-panel.mjs"; done
for f in hg-pista-900.webp hg-pista-1440.webp hg-campo-900.webp hg-campo-1440.webp; do e "$f" "Origen: captura del tráiler de Haría Game (github.com/fmoorenoo/HariaGame), versión compilada para Windows de la carpeta de Drive del README, ejecutada en local el 30-10-2026; recortado el botón «Salir»"; done
for f in hg-entrada-900.webp hg-entrada-1440.webp hg-planta-900.webp hg-planta-1440.webp hg-paseo-900.webp hg-paseo-1440.webp; do e "$f" "Origen: captura del menú de Haría Game (cámara recorriendo el instituto), versión compilada para Windows ejecutada en local el 30-10-2026"; done
for f in hg-readme-partida-900.webp hg-readme-partida-1440.webp hg-readme-menu-900.webp hg-readme-menu-1440.webp; do e "$f" "Origen: captura original del README de github.com/fmoorenoo/HariaGame (hecha por Fernando Montelongo)"; done
for f in hg-cmp-real-paseo-600.webp hg-cmp-real-paseo-960.webp hg-cmp-real-edificio-600.webp hg-cmp-real-edificio-960.webp hg-cmp-real-rotulo-600.webp hg-cmp-real-rotulo-960.webp; do e "$f" "Origen: fotografía real del IES Haría aportada por Fernando Montelongo el 30-10-2026 (assets-src/hariagame/real), recortada a 16:9 para la comparación con el juego"; done
for f in hg-cmp-juego-paseo-600.webp hg-cmp-juego-paseo-960.webp hg-cmp-juego-edificio-600.webp hg-cmp-juego-edificio-960.webp hg-cmp-juego-rotulo-600.webp hg-cmp-juego-rotulo-960.webp; do e "$f" "Origen: captura de Haría Game (versión para Windows ejecutada en local el 30-10-2026, o README del repositorio para la partida), recortada a 16:9 para emparejarla con la foto real"; done
